# Hypothesis: fill diagonals - if a cell is diagonally adjacent to a 5, make it 5

def fill_diagonals(grid):
    result = [row[:] for row in grid]  # Copy
    for r in range(9):
        for c in range(7, 13):  # Only right side
            if result[r][c] == 5:
                # Check all 8 diagonal neighbors
                for dr in [-1, 1]:
                    for dc in [-1, 1]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < 9 and 0 <= nc < 13:
                            if result[nr][nc] != 5:  # Already 5, skip
                                result[nr][nc] = 5
    return result

